CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Achievements" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" text NOT NULL,
    "Description" text NOT NULL,
    "Icon" text NOT NULL,
    "RequiredXp" integer NOT NULL,
    CONSTRAINT "PK_Achievements" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoles" (
    "Id" text NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetUsers" (
    "Id" text NOT NULL,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);

CREATE TABLE "ProgrammingLanguages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Slug" text NOT NULL,
    "Description" text NOT NULL,
    "Color" text NOT NULL,
    "Difficulty" text NOT NULL,
    "Available" boolean NOT NULL,
    CONSTRAINT "PK_ProgrammingLanguages" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Classes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TeacherId" text NOT NULL,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Classes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Classes_AspNetUsers_TeacherId" FOREIGN KEY ("TeacherId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StudentAchievements" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "AchievementId" integer NOT NULL,
    "EarnedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_StudentAchievements" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StudentAchievements_Achievements_AchievementId" FOREIGN KEY ("AchievementId") REFERENCES "Achievements" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StudentAchievements_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "StudentProfiles" (
    "UserId" text NOT NULL,
    "Nickname" text NOT NULL,
    "Avatar" text NOT NULL,
    "AgeBand" text NOT NULL,
    "GuardianConsent" boolean NOT NULL,
    "LeaderboardOptIn" boolean NOT NULL,
    "Xp" integer NOT NULL,
    CONSTRAINT "PK_StudentProfiles" PRIMARY KEY ("UserId"),
    CONSTRAINT "CK_Profile_Xp" CHECK ("Xp" >= 0),
    CONSTRAINT "FK_StudentProfiles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "XPTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Source" text NOT NULL,
    "Amount" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_XPTransactions" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Xp_Positive" CHECK ("Amount" > 0),
    CONSTRAINT "FK_XPTransactions_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Courses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LanguageId" integer NOT NULL,
    "Title" text NOT NULL,
    "Description" text NOT NULL,
    "TeacherId" text,
    "Published" boolean NOT NULL,
    CONSTRAINT "PK_Courses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Courses_AspNetUsers_TeacherId" FOREIGN KEY ("TeacherId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Courses_ProgrammingLanguages_LanguageId" FOREIGN KEY ("LanguageId") REFERENCES "ProgrammingLanguages" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ClassEnrollments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClassId" integer NOT NULL,
    "StudentId" text NOT NULL,
    CONSTRAINT "PK_ClassEnrollments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ClassEnrollments_AspNetUsers_StudentId" FOREIGN KEY ("StudentId") REFERENCES "AspNetUsers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ClassEnrollments_Classes_ClassId" FOREIGN KEY ("ClassId") REFERENCES "Classes" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Chapters" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CourseId" integer NOT NULL,
    "Title" text NOT NULL,
    "Position" integer NOT NULL,
    CONSTRAINT "PK_Chapters" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Chapters_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES "Courses" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Lessons" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ChapterId" integer NOT NULL,
    "Title" text NOT NULL,
    "Position" integer NOT NULL,
    "Published" boolean NOT NULL,
    CONSTRAINT "PK_Lessons" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Lessons_Chapters_ChapterId" FOREIGN KEY ("ChapterId") REFERENCES "Chapters" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CodingChallenges" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LessonId" integer NOT NULL,
    "Title" text NOT NULL,
    "Description" text NOT NULL,
    "StarterCode" text NOT NULL,
    "Xp" integer NOT NULL,
    CONSTRAINT "PK_CodingChallenges" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CodingChallenges_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Exercises" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LessonId" integer NOT NULL,
    "Mode" text NOT NULL,
    "Prompt" text NOT NULL,
    "Template" text NOT NULL,
    "Level" integer NOT NULL,
    "Xp" integer NOT NULL,
    CONSTRAINT "PK_Exercises" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Exercises_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE CASCADE
);

CREATE TABLE "LessonContents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LessonId" integer NOT NULL,
    "Objectives" text NOT NULL,
    "Explanation" text NOT NULL,
    "Example" text NOT NULL,
    "Notes" text NOT NULL,
    "Quiz" text NOT NULL,
    "QuizOptions" text[] NOT NULL,
    "QuizAnswer" integer NOT NULL,
    CONSTRAINT "PK_LessonContents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_LessonContents_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE CASCADE
);

CREATE TABLE "StudentAttempts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "LessonId" integer NOT NULL,
    "Mode" text NOT NULL,
    "Score" integer NOT NULL,
    "IncorrectPositions" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_StudentAttempts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StudentAttempts_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StudentAttempts_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StudentProgress" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "LessonId" integer NOT NULL,
    "Theory" boolean NOT NULL,
    "Drag" boolean NOT NULL,
    "Memory" boolean NOT NULL,
    "Challenge" boolean NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_StudentProgress" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StudentProgress_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StudentProgress_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Videos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LessonId" integer NOT NULL,
    "Url" text NOT NULL,
    "Title" text NOT NULL,
    CONSTRAINT "PK_Videos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Videos_Lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES "Lessons" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Submissions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ChallengeId" integer NOT NULL,
    "Code" text NOT NULL,
    "IsPractice" boolean NOT NULL,
    "Score" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Submissions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Submissions_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Submissions_CodingChallenges_ChallengeId" FOREIGN KEY ("ChallengeId") REFERENCES "CodingChallenges" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "TestCases" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ChallengeId" integer NOT NULL,
    "Input" text NOT NULL,
    "Expected" text NOT NULL,
    "IsSample" boolean NOT NULL,
    "CodingChallengeId" integer,
    CONSTRAINT "PK_TestCases" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TestCases_CodingChallenges_CodingChallengeId" FOREIGN KEY ("CodingChallengeId") REFERENCES "CodingChallenges" ("Id")
);

CREATE TABLE "ExerciseBlanks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ExerciseId" integer NOT NULL,
    "Position" integer NOT NULL,
    "Hints" text[] NOT NULL,
    CONSTRAINT "PK_ExerciseBlanks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExerciseBlanks_Exercises_ExerciseId" FOREIGN KEY ("ExerciseId") REFERENCES "Exercises" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ExerciseOptions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ExerciseId" integer NOT NULL,
    "Value" text NOT NULL,
    CONSTRAINT "PK_ExerciseOptions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExerciseOptions_Exercises_ExerciseId" FOREIGN KEY ("ExerciseId") REFERENCES "Exercises" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SubmissionResults" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SubmissionId" integer NOT NULL,
    "TestCaseId" integer NOT NULL,
    "Passed" boolean NOT NULL,
    "Output" text NOT NULL,
    "Error" text NOT NULL,
    CONSTRAINT "PK_SubmissionResults" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SubmissionResults_Submissions_SubmissionId" FOREIGN KEY ("SubmissionId") REFERENCES "Submissions" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_SubmissionResults_TestCases_TestCaseId" FOREIGN KEY ("TestCaseId") REFERENCES "TestCases" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ExerciseAnswers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BlankId" integer NOT NULL,
    "Value" text NOT NULL,
    CONSTRAINT "PK_ExerciseAnswers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExerciseAnswers_ExerciseBlanks_BlankId" FOREIGN KEY ("BlankId") REFERENCES "ExerciseBlanks" ("Id") ON DELETE CASCADE
);

